}

.cartItem {
  padding: 18px 0;

  display: grid;
  grid-template-columns:
    90px 1fr;
  gap: 14px;

  border-bottom:
    1px solid #eee4df;
}

.cartItem img {
  width: 90px;
  height: 120px;

  object-fit: cover;
  border-radius: 8px;
}

.cartItemInfo {
  display: flex;
  flex-direction: column;
}

.cartItemInfo h4 {
  margin: 0 0 7px;

  font-family:
    "Playfair Display",
    serif;

  font-size: 17px;
}

.cartItemInfo > strong {
  color: #77364c;
  font-size: 10px;
}

.quantity {
  margin-top: 14px;

  display: flex;
  align-items: center;
  gap: 11px;
}

.quantity button {
  width: 27px;
  height: 27px;

  border:
    1px solid #e5dad6;

  border-radius: 50%;

  background: white;
}

.quantity span {
  font-size: 10px;
  font-weight: 700;
}

.remove {
  align-self: flex-start;

  margin-top: auto;
  padding: 0;

  border: 0;
  background: transparent;

  color: #9c5367;

  font-size: 8px;
  text-decoration: underline;
}

.cartFooter {
  padding: 20px;

  border-top:
    1px solid #eee4df;
}

.total {
  display: flex;
  justify-content: space-between;
}

.total strong {
  color: #77364c;
}

.cartFooter p {
  color: #857980;
  font-size: 8px;
}

.checkout {
  width: 100%;
  height: 50px;

  margin-top: 8px;

  border: 0;
  border-radius: 999px;

  background: #435c4e;
  color: white;

  font-size: 10px;
  font-weight: 700;
}

/* RESPONSIVE */

@media(max-width: 900px) {
  nav {
    display: none;
  }

  .hero {
    grid-template-columns: 1fr;
  }

  .heroContent {
    text-align: center;
  }

  .heroContent > p {
    margin-left: auto;
    margin-right: auto;
  }

  .heroButtons,
  .advantages {
    justify-content: center;
  }

  .heroVisual {
    max-width: 600px;
    width: 100%;
    margin: auto;
  }

  .services {
    margin-left: 20px;
    margin-right: 20px;
  }

  .products {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .about {
    grid-template-columns: 1fr;
  }

  .aboutImage {
    width: min(600px, 100%);
    margin: auto;
  }
}

@media(max-width: 600px) {
  .topbar {
    font-size: 8px;
  }

  .topbar .dot,
  .topbar span:last-child {
    display: none;
  }

  .header {
    height: 69px;
    padding: 0 15px;
  }

  .logo strong {
    font-size: 10px;
  }

  .logo small {
    font-size: 6px;
  }

  .logout {
    display: none;
  }

  .cartButton {
    width: 42px;
    padding: 0;
    justify-content: center;
    position: relative;
  }

  .cartText {
    display: none;
  }

  .cartButton b {
    position: absolute;
    top: -3px;
    right: -3px;

    width: 17px;
    height: 17px;

    background: #a44561;
    color: white;

    border:
      2px solid white;
  }

  .hero {
    padding:
      45px 18px 70px;
  }

  .hero h1 {
    font-size: 47px;
  }

  .heroContent > p {
    font-size: 12px;
  }

  .heroButtons {
    flex-direction: column;
  }

  .advantages {
    display: grid;
  }

  .heroVisual {
    height: 420px;
  }

  .heroCircle {
    width: 290px;
    height: 290px;
    right: 0;
  }

  .heroMain {
    width: 69%;
    right: 2%;
  }

  .heroSmall {
    width: 35%;
    left: 0;
  }

  .heroLock {
    width: 150px;
    padding: 15px;
  }

  .heroProduct {
    width: 145px;
    padding: 12px;
  }

  .services {
    grid-template-columns: 1fr;
    padding: 10px 18px;
  }

  .services > div {
    border-right: 0;
    border-bottom:
      1px solid #eee2dc;

    padding: 15px 5px;
  }

  .collection {
    padding:
      80px 12px;
  }

  .collectionHeader {
    flex-direction: column;
    align-items: stretch;
  }

  .collection h2 {
    font-size: 37px;
  }

  .searchBox {
    width: 100%;
  }

  .products {
    gap: 25px 9px;
  }

  .productImage {
    height: 270px;
  }

  .imageLock {
    width: 115px;
    height: 85px;
  }

  .imageLock strong {
    font-size: 8px;
  }

  .imageLock small {
    font-size: 6px;
  }

  .addButton {
    opacity: 1;
    transform: none;

    left: 8px;
    right: 8px;
    bottom: 8px;

    height: 36px;
    font-size: 7px;
  }

  .productInfo h3 {
    font-size: 15px;
  }

  .sizes {
    display: none;
  }

  .about {
    padding:
      75px 20px;
  }

  .aboutImage {
    height: 420px;
  }

  .about h2 {
    font-size: 46px;
  }

  .loginModal {
    padding:
      32px 19px 23px;

    border-radius: 18px;
  }

  .loginModal h2 {
    font-size: 24px;
  }

  .selectedProduct {
    margin-top: 17px;
  }
}
