import React, { useMemo, useState } from "react";

const products = [
  {
    id: 1,
    name: "Robe Soa",
    category: "Nouveautés",
    price: 129000,
    oldPrice: 149000,
    image:
      "https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 2,
    name: "Robe Mialy",
    category: "Soirée",
    price: 159000,
    image:
      "https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 3,
    name: "Robe Vola",
    category: "Décontractée",
    price: 99000,
    image:
      "https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 4,
    name: "Robe Fara",
    category: "Cérémonie",
    price: 139000,
    image:
      "https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 5,
    name: "Robe Kanto",
    category: "Décontractée",
    price: 119000,
    image:
      "https://images.unsplash.com/photo-1539109136881-3be0616acf4b?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 6,
    name: "Robe Tahina",
    category: "Soirée",
    price: 179000,
    image:
      "https://images.unsplash.com/photo-1502716119720-b23a1e3ae1b5?auto=format&fit=crop&w=900&q=85",
  },
];

const categories = [
  "Toutes",
  "Nouveautés",
  "Soirée",
  "Cérémonie",
  "Décontractée",
];

const formatPrice = (price) =>
  new Intl.NumberFormat("fr-FR").format(price) + " Ar";

export default function App() {
  const [category, setCategory] = useState("Toutes");
  const [search, setSearch] = useState("");

  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);

  const [favorites, setFavorites] = useState([]);

  const [loginOpen, setLoginOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  // Démo : passe à true après une connexion interne simulée.
  // Avec ton backend, remplace ceci par l'état réel de session.
  const [loggedIn, setLoggedIn] = useState(false);

  const [emailMode, setEmailMode] = useState(false);
  const [email, setEmail] = useState("");

  const filteredProducts = useMemo(() => {
    return products.filter((product) => {
      const categoryMatch =
        category === "Toutes" || product.category === category;

      const searchMatch = product.name
        .toLowerCase()
        .includes(search.toLowerCase());

      return categoryMatch && searchMatch;
    });
  }, [category, search]);

  const openImage = (product) => {
    if (loggedIn) return;

    setSelectedProduct(product);
    setLoginOpen(true);
  };

  const addToCart = (product) => {
    if (!loggedIn) {
      setSelectedProduct(product);
      setLoginOpen(true);
      return;
    }

    setCart((current) => {
      const exists = current.find((item) => item.id === product.id);

      if (exists) {
        return current.map((item) =>
          item.id === product.id
            ? {
                ...item,
                quantity: item.quantity + 1,
              }
            : item
        );
      }

      return [...current, { ...product, quantity: 1 }];
    });

    setCartOpen(true);
  };

  const toggleFavorite = (product) => {
    if (!loggedIn) {
      setSelectedProduct(product);
      setLoginOpen(true);
      return;
    }

    setFavorites((current) =>
      current.includes(product.id)
        ? current.filter((id) => id !== product.id)
        : [...current, product.id]
    );
  };

  const changeQuantity = (id, amount) => {
    setCart((current) =>
      current
        .map((item) =>
          item.id === id
            ? {
                ...item,
                quantity: item.quantity + amount,
              }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const removeFromCart = (id) => {
    setCart((current) =>
      current.filter((item) => item.id !== id)
    );
  };

  const cartCount = cart.reduce(
    (total, item) => total + item.quantity,
    0
  );

  const cartTotal = cart.reduce(
    (total, item) =>
      total + item.price * item.quantity,
    0
  );

  const loginWithFacebook = () => {
    /*
      IMPORTANT

      Ce bouton doit rediriger vers TON backend.

      Exemple Node/Express :
      GET /auth/facebook

      Ton backend redirigera ensuite vers
      l'authentification officielle Meta/Facebook.

      Ne crée pas de formulaire qui demande
      l'adresse Facebook + mot de passe Facebook ici.
    */

    window.location.href = "/auth/facebook";
  };

  const demoLogin = (event) => {
    event.preventDefault();

    if (!email.trim()) return;

    setLoggedIn(true);
    setLoginOpen(false);
    setEmailMode(false);
    setEmail("");
  };

  const logout = () => {
    setLoggedIn(false);
    setCart([]);
    setFavorites([]);
  };

  const orderWhatsApp = () => {
    const items = cart
      .map(
        (item) =>
          `${item.name} x${item.quantity} — ${formatPrice(
            item.price * item.quantity
          )}`
      )
      .join("\n");

    const message = `Bonjour Ravaka 👋

Je souhaite commander :

${items}

Total : ${formatPrice(cartTotal)}`;

    const whatsappNumber = "261340000000";

    window.open(
      `https://wa.me/${whatsappNumber}?text=${encodeURIComponent(
        message
      )}`,
      "_blank"
    );
  };

  return (
    <>
      <style>{css}</style>

      <div className="shop">
        {/* TOP BAR */}

        <div className="topbar">
          <span>🇲🇬 Livraison partout à Madagascar</span>

          <span className="dot">•</span>

          <span>
            Paiement MVola • Orange Money • Airtel Money
          </span>
        </div>

        {/* HEADER */}

        <header className="header">
          <a href="#" className="logo">
            <div className="logoIcon">R</div>

            <div>
              <strong>RAVAKA</strong>
              <small>FEMME • MADAGASCAR</small>
            </div>
          </a>

          <nav>
            <a href="#collection">Nouveautés</a>
            <a href="#collection">Robes</a>
            <a href="#about">Notre univers</a>
            <a href="#delivery">Livraison</a>
          </nav>

          <div className="headerActions">
            {loggedIn && (
              <button
                className="logout"
                onClick={logout}
              >
                Déconnexion
              </button>
            )}

            <button
              className="cartButton"
              onClick={() => setCartOpen(true)}
            >
              <span>🛍️</span>

              <span className="cartText">
                Panier
              </span>

              <b>{cartCount}</b>
            </button>
          </div>
        </header>

        {/* HERO */}

        <section className="hero">
          <div className="heroContent">
            <span className="smallTitle">
              ✦ COLLECTION FEMME
            </span>

            <h1>
              Des robes pensées
              <br />
              pour vous faire
              <em> rayonner.</em>
            </h1>

            <p>
              Découvrez une collection féminine,
              moderne et élégante, disponible à
              Madagascar.
            </p>

            {!loggedIn && (
              <div className="heroNotice">
                🔒 Connectez-vous pour découvrir les
                photos de la collection.
              </div>
            )}

            {loggedIn && (
              <div className="connected">
                ✓ Vous êtes connectée — collection
                débloquée
              </div>
            )}

            <div className="heroButtons">
              <a
                href="#collection"
                className="primaryButton"
              >
                Découvrir la collection
                <span>→</span>
              </a>

              <a
                href="#about"
                className="simpleLink"
              >
                Notre histoire
              </a>
            </div>

            <div className="advantages">
              <span>✓ Prix en Ariary</span>
              <span>✓ Livraison Madagascar</span>
              <span>✓ Commande WhatsApp</span>
            </div>
          </div>

          <div
            className={`heroVisual ${
              loggedIn ? "unlocked" : ""
            }`}
            onClick={() => {
              if (!loggedIn) setLoginOpen(true);
            }}
          >
            <div className="heroCircle" />

            <img
              className="heroMain"
              src="https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=1000&q=90"
              alt="Collection de robes Ravaka"
            />

            <img
              className="heroSmall"
              src="https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=600&q=90"
              alt="Robe femme Ravaka"
            />

            {!loggedIn && (
              <div className="heroLock">
                <div className="lockCircle">
                  🔒
                </div>

                <strong>
                  Collection privée
                </strong>

                <small>
                  Cliquez pour voir les photos
                </small>
              </div>
            )}

            <div className="heroProduct">
              <small>NOUVELLE PIÈCE</small>
              <strong>Robe Mialy</strong>
              <span>159 000 Ar</span>
            </div>
          </div>
        </section>

        {/* SERVICES */}

        <section
          className="services"
          id="delivery"
        >
          <div>
            <span>🚚</span>

            <section>
              <strong>
                Livraison Madagascar
              </strong>

              <small>
                Antananarivo & provinces
              </small>
            </section>
          </div>

          <div>
            <span>📱</span>

            <section>
              <strong>
                Paiement mobile
              </strong>

              <small>
                MVola, Orange Money, Airtel Money
              </small>
            </section>
          </div>

          <div>
            <span>💬</span>

            <section>
              <strong>
                Commande WhatsApp
              </strong>

              <small>
                Assistance rapide
              </small>
            </section>
          </div>
        </section>

        {/* COLLECTION */}

        <section
          className="collection"
          id="collection"
        >
          <div className="collectionHeader">
            <div>
              <span className="smallTitle">
                SÉLECTION RAVAKA
              </span>

              <h2>
                Les robes du moment
              </h2>
            </div>

            <div className="searchBox">
              <span>⌕</span>

              <input
                type="search"
                placeholder="Rechercher..."
                value={search}
                onChange={(event) =>
                  setSearch(event.target.value)
                }
              />
            </div>
          </div>

          {/* FILTERS */}

          <div className="categories">
            {categories.map((item) => (
              <button
                key={item}
                className={
                  category === item
                    ? "active"
                    : ""
                }
                onClick={() =>
                  setCategory(item)
                }
              >
                {item}
              </button>
            ))}
          </div>

          {/* PRODUCTS */}

          <div className="products">
            {filteredProducts.map(
              (product) => {
                const liked =
                  favorites.includes(product.id);

                return (
                  <article
                    className="product"
                    key={product.id}
                  >
                    <div className="productImage">
                      <img
                        src={product.image}
                        alt={product.name}
                        className={
                          loggedIn
                            ? "visibleImage"
                            : "blurredImage"
                        }
                        onClick={() =>
                          openImage(product)
                        }
                      />

                      {!loggedIn && (
                        <button
                          className="imageLock"
                          onClick={() =>
                            openImage(product)
                          }
                        >
                          <span>🔒</span>

                          <strong>
                            Voir la photo
                          </strong>

                          <small>
                            Connexion requise
                          </small>
                        </button>
                      )}

                      <span className="productCategory">
                        {product.category}
                      </span>

                      <button
                        className={`heart ${
                          liked ? "liked" : ""
                        }`}
                        onClick={() =>
                          toggleFavorite(product)
                        }
                      >
                        {liked ? "♥" : "♡"}
                      </button>

                      {loggedIn && (
                        <button
                          className="addButton"
                          onClick={() =>
                            addToCart(product)
                          }
                        >
                          Ajouter au panier
                        </button>
                      )}
                    </div>

                    <div className="productInfo">
                      <small>
                        {product.category}
                      </small>

                      <h3>
                        {product.name}
                      </h3>

                      <div className="price">
                        <strong>
                          {formatPrice(
                            product.price
                          )}
                        </strong>

                        {product.oldPrice && (
                          <del>
                            {formatPrice(
                              product.oldPrice
                            )}
                          </del>
                        )}
                      </div>

                      <div className="sizes">
                        <span>S</span>
                        <span>M</span>
                        <span>L</span>
                        <span>XL</span>
                      </div>
                    </div>
                  </article>
                );
              }
            )}
          </div>
        </section>

        {/* ABOUT */}

        <section
          className="about"
          id="about"
        >
          <div
            className={`aboutImage ${
              loggedIn ? "unlocked" : ""
            }`}
            onClick={() => {
              if (!loggedIn)
                setLoginOpen(true);
            }}
          >
            <img
              src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1100&q=85"
              alt="Boutique Ravaka"
            />

            {!loggedIn && (
              <div className="aboutLock">
                🔒
              </div>
            )}
          </div>

          <div className="aboutText">
            <span className="smallTitle">
              NOTRE UNIVERS
            </span>

            <h2>
              Élégante.
              <br />
              Moderne.
              <br />
              <em>Malagasy.</em>
            </h2>

            <p>
              Ravaka vous propose une expérience
              shopping simple et moderne pour
              découvrir de belles robes directement
              depuis votre téléphone.
            </p>

            <ul>
              <li>
                ✓ Commande simple
              </li>

              <li>
                ✓ Assistance WhatsApp
              </li>

              <li>
                ✓ Prix en Ariary
              </li>

              <li>
                ✓ Livraison nationale
              </li>
            </ul>

            <a
              className="whatsapp"
              href="https://wa.me/261340000000"
              target="_blank"
              rel="noreferrer"
            >
              💬 Contacter Ravaka
            </a>
          </div>
        </section>

        {/* FOOTER */}

        <footer>
          <div className="footerLogo">
            <div className="logoIcon">
              R
            </div>

            <div>
              <strong>RAVAKA</strong>
              <small>
                FEMME • MADAGASCAR
              </small>
            </div>
          </div>

          <p>
            Boutique de robes femme à
            Madagascar.
          </p>

          <div className="socials">
            <a href="#">Instagram</a>
            <a href="#">Facebook</a>
            <a href="#">TikTok</a>
          </div>

          <small>
            © 2026 Ravaka Madagascar
          </small>
        </footer>

        {/* LOGIN MODAL */}

        {loginOpen && (
          <div
            className="loginOverlay"
            onClick={() => {
              setLoginOpen(false);
              setEmailMode(false);
            }}
          >
            <div
              className="loginModal"
              onClick={(event) =>
                event.stopPropagation()
              }
            >
              <button
                className="closeLogin"
                onClick={() => {
                  setLoginOpen(false);
                  setEmailMode(false);
                }}
              >
                ×
              </button>

              <div className="modalBrand">
                <div className="modalLogo">
                  R
                </div>

                <strong>
                  RAVAKA
                </strong>

                <small>
                  FEMME • MADAGASCAR
                </small>
              </div>

              {selectedProduct && (
                <div className="selectedProduct">
                  <img
                    src={selectedProduct.image}
                    alt=""
                  />

                  <div>
                    <small>
                      VOUS SOUHAITEZ VOIR
                    </small>

                    <strong>
                      {selectedProduct.name}
                    </strong>
                  </div>
                </div>
              )}

              {!emailMode ? (
                <>
                  <h2>
                    Connectez-vous pour
                    découvrir la collection
                  </h2>

                  <p className="modalDescription">
                    Accédez aux photos,
                    enregistrez vos favoris
                    et commandez vos robes.
                  </p>

                  <button
                    className="facebookButton"
                    onClick={
                      loginWithFacebook
                    }
                  >
                    <span className="fbIcon">
                      f
                    </span>

                    Continuer avec Facebook
                  </button>

                  <button
                    className="googleButton"
                    onClick={() => {
                      window.location.href =
                        "/auth/google";
                    }}
                  >
                    <span className="googleIcon">
                      G
                    </span>

                    Continuer avec Google
                  </button>

                  <div className="separator">
                    <span />
                    <small>OU</small>
                    <span />
                  </div>

                  <button
                    className="emailButton"
                    onClick={() =>
                      setEmailMode(true)
                    }
                  >
                    Continuer avec mon e-mail
                  </button>
                </>
              ) : (
                <form
                  className="emailForm"
                  onSubmit={demoLogin}
                >
                  <button
                    type="button"
                    className="backButton"
                    onClick={() =>
                      setEmailMode(false)
                    }
                  >
                    ← Retour
                  </button>

                  <h2>
                    Se connecter
                  </h2>

                  <p>
                    Entrez votre adresse
                    e-mail pour continuer.
                  </p>

                  <label>
                    Adresse e-mail
                  </label>

                  <input
                    autoFocus
                    type="email"
                    placeholder="vous@email.com"
                    value={email}
                    onChange={(event) =>
                      setEmail(
                        event.target.value
                      )
                    }
                    required
                  />

                  <button
                    className="continueButton"
                    type="submit"
                  >
                    Continuer
                  </button>

                  <small className="demoMessage">
                    Cette connexion e-mail
                    est uniquement une
                    démonstration front-end.
                  </small>
                </form>
              )}

              {!emailMode && (
                <p className="privacy">
                  En continuant, vous acceptez
                  les conditions d'utilisation
                  et la politique de
                  confidentialité de Ravaka.
                </p>
              )}
            </div>
          </div>
        )}

        {/* CART */}

        {cartOpen && (
          <div
            className="cartOverlay"
            onClick={() =>
              setCartOpen(false)
            }
          >
            <aside
              className="cartDrawer"
              onClick={(event) =>
                event.stopPropagation()
              }
            >
              <div className="cartHeader">
                <div>
                  <h2>
                    Votre panier
                  </h2>

                  <small>
                    {cartCount} article(s)
                  </small>
                </div>

                <button
                  onClick={() =>
                    setCartOpen(false)
                  }
                >
                  ×
                </button>
              </div>

              <div className="cartContent">
                {cart.length === 0 ? (
                  <div className="emptyCart">
                    <span>🛍️</span>

                    <h3>
                      Votre panier est vide
                    </h3>

                    <p>
                      Découvrez notre
                      collection de robes.
                    </p>
                  </div>
                ) : (
                  cart.map((item) => (
                    <div
                      className="cartItem"
                      key={item.id}
                    >
                      <img
                        src={item.image}
                        alt={item.name}
                      />

                      <div className="cartItemInfo">
                        <h4>
                          {item.name}
                        </h4>

                        <strong>
                          {formatPrice(
                            item.price
                          )}
                        </strong>

                        <div className="quantity">
                          <button
                            onClick={() =>
                              changeQuantity(
                                item.id,
                                -1
                              )
                            }
                          >
                            −
                          </button>

                          <span>
                            {item.quantity}
                          </span>

                          <button
                            onClick={() =>
                              changeQuantity(
                                item.id,
                                1
                              )
                            }
                          >
                            +
                          </button>
                        </div>

                        <button
                          className="remove"
                          onClick={() =>
                            removeFromCart(
                              item.id
                            )
                          }
                        >
                          Supprimer
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>

              {cart.length > 0 && (
                <div className="cartFooter">
                  <div className="total">
                    <span>Total</span>

                    <strong>
                      {formatPrice(
                        cartTotal
                      )}
                    </strong>
                  </div>

                  <p>
                    Les frais de livraison
                    seront confirmés lors de
                    la commande.
                  </p>

                  <button
                    className="checkout"
                    onClick={
                      orderWhatsApp
                    }
                  >
                    Commander sur
                    WhatsApp →
                  </button>
                </div>
              )}
            </aside>
          </div>
        )}
      </div>
    </>
  );
}

const css = `
